// Diagnostic probe generated by ppl (safe to delete).
// Tests Notes() assignment forms: variable RHS (proven), literal RHS,
// literal-empty delete (documented form), variable-empty delete, read-back.
EXPORT ZZT_PROBE2()
BEGIN
  LOCAL r,e,ok;
  PRINT("P2 start");
  r:="p1-varwrite";
  Notes("ZZT_PROBER"):=r;
  PRINT("p1 ok");
  ok:=1;
  IFERR Notes("ZZT_PROBER"):="p2-litwrite"; THEN ok:=0; END;
  IF ok THEN r:="p2-litwrite-ok"; ELSE r:="p2-litwrite-ERR"; END;
  Notes("ZZT_PROBER"):=r;
  PRINT(r);
  ok:=1;
  IFERR Notes("ZZT_POCN1"):=""; THEN ok:=0; END;
  IF ok THEN r:="p3-litdel-ok"; ELSE r:="p3-litdel-ERR"; END;
  Notes("ZZT_PROBER"):=r;
  PRINT(r);
  e:="";
  ok:=1;
  IFERR Notes("ZZT_POCN1"):=e; THEN ok:=0; END;
  IF ok THEN r:="p4-vardel-ok"; ELSE r:="p4-vardel-ERR"; END;
  Notes("ZZT_PROBER"):=r;
  PRINT(r);
  r:="?";
  ok:=1;
  IFERR r:=Notes("ZZT_POCN1"); THEN ok:=0; END;
  IF ok THEN PRINT("readback:["+r+"]"); ELSE PRINT("readback:ERR"); END;
  r:="p5-notes-done";
  Notes("ZZT_PROBER"):=r;
  PRINT("P2 done");
  RETURN 0;
END;
